from heapq import heappop, heappush


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    times = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(times)}
    m = len(times)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(idx[start], idx[end], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    total_cost = 0
    for _ in range(k):
        dist = [INF] * m
        dist[0] = 0
        parent_node = [-1] * m
        parent_edge = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_node[v] = u
                        parent_edge[v] = ei
                        heappush(pq, (nd, v))

        if dist[m - 1] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        path_cost = pot[m - 1] - pot[0]
        if path_cost >= 0:
            break

        total_cost += path_cost
        v = m - 1
        while v != 0:
            u = parent_node[v]
            ei = parent_edge[v]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[v][edge[3]][1] += 1
            v = u

    return -total_cost
